$s=auth();$user=$s['user_id'];$method=$_SERVER['REQUEST_METHOD'];$b=[];if($method==='POST'){$b=body();csrf($s);}elseif($method!=='GET')fail('Método não permitido.',405);$shop=clean($_GET['shop']??$b['shop']??'alan-barber');$isAdmin=(bool)row('SELECT 1 FROM members WHERE shop=? AND "user"=? AND role=?',[$shop,$user,'admin']);
