if($path==='bookings'&&$method==='POST'){$id=transaction(function()use($shop,$user,$s,$b){$store=row('SELECT * FROM shops WHERE id=?',[$shop]);if(!$store)fail('Barbearia indisponível.');$block=($b['type']??'')==='block';$manual=($b['manual']??false)===true;$customer=$user;$name=$s['name'];$phone=$s['phone'];if($block||$manual){admin($shop,$user);$customer=null;$name=clean($b['name']??'')?:'Indisponível';$phone=phone($b['phone']??'');}if(!$block&&(strlen($name)<2||strlen($phone)<10||strlen($phone)>15))fail('Preencha nome e telefone válidos.');$service=$block?['id'=>null,'name'=>'Bloqueio de agenda','duration'=>num($b['duration']??0,5,600),'price'=>0]:row('SELECT * FROM services WHERE id=? AND shop=? AND active=1',[clean($b['service']??''),$shop]);$staff=clean($b['staff']??'');if(!$service||!row('SELECT id FROM staff WHERE id=? AND shop=? AND active=1',[$staff,$shop]))fail('Serviço ou profissional indisponível.');$start=num($b['start']??0,1,9999999999);$end=$start+$service['duration']*60;$release=$end+($block?0:$store['buffer']*60);if($block){if($start<time()||$end>time()+91*86400)fail('Período inválido.');}else validTime($start,$end,$release,$store);conflict(['shop'=>$shop,'staff'=>$staff,'user'=>$customer,'phone'=>$phone,'start'=>$start,'release'=>$release]);$id=id();q('INSERT INTO bookings VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)',[$id,$shop,$customer,$staff,$service['id'],$name,$phone,$service['name'],$service['price'],$start,$end,$release,$block?'blocked':'confirmed',clean($b['notes']??'',500),time(),time()]);audit($shop,$user,$block?'block':'book',$id);return $id;});out(['id'=>$id],201);}
