if($path==='dashboard'&&$method==='GET'){admin($shop,$user);$d=day(clean($_GET['date']??''));out(['day'=>row('SELECT count(*) total,coalesce(sum(CASE WHEN status=\'completed\' THEN price ELSE 0 END),0) revenue,coalesce(sum(CASE WHEN status=\'confirmed\' THEN 1 ELSE 0 END),0) upcoming FROM bookings WHERE shop=? AND start>=? AND start<? AND status NOT IN (\'blocked\',\'cancelled\')',[$shop,$d['start'],$d['end']]),'clients'=>rows('SELECT max(name) name,phone,count(*) visits,max(start) last_visit FROM bookings WHERE shop=? AND status!=\'blocked\' GROUP BY phone ORDER BY last_visit DESC LIMIT 200',[$shop]),'services'=>rows('SELECT * FROM services WHERE shop=?',[$shop]),'staff'=>rows('SELECT * FROM staff WHERE shop=?',[$shop]),'audit'=>rows('SELECT action,target,created FROM audit WHERE shop=? ORDER BY created DESC LIMIT 30',[$shop])]);}
