if(in_array($path,['service','staff'],true)&&$method==='POST'){admin($shop,$user);$id=clean($b['id']??'')?:id();$name=clean($b['name']??'');if(strlen($name)<2)fail('Informe o nome.');$table=$path==='service'?'services':'staff';$old=row("SELECT shop FROM $table WHERE id=?",[$id]);if($old&&$old['shop']!==$shop)fail('Acesso negado.',403);$active=($b['active']??true)===false?0:1;if($path==='service')q('INSERT INTO services VALUES(?,?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,duration=excluded.duration,price=excluded.price,active=excluded.active',[$id,$shop,$name,num($b['duration']??0,5,360),num($b['price']??0,0,1000000),$active]);else q('INSERT INTO staff VALUES(?,?,?,?) ON CONFLICT(id) DO UPDATE SET name=excluded.name,active=excluded.active',[$id,$shop,$name,$active]);audit($shop,$user,$path,$id);out(['ok'=>true]);}
if($path==='workspace'&&$method==='POST'){if(!row('SELECT 1 FROM system_state WHERE key=? AND value=?',['owner_initialized',$user]))fail('Acesso exclusivo do proprietário.',403);$name=clean($b['name']??'');if(strlen($name)<2)fail('Informe o nome.');$id=id();transaction(function()use($id,$name,$user){q('INSERT INTO shops(id,name,owner) VALUES(?,?,?)',[$id,$name,$user]);q('INSERT INTO members VALUES(?,?,?)',[$id,$user,'admin']);});out(['id'=>$id]);}
fail('Rota não encontrada.',404);
